// Lote 1b, tool 8: battery health, a line-by-line port of src/shared/batteryhealth.ts. Pure C# (no UnityEngine), so the EditMode golden test
// (contracts/golden/battery.json, generated by the web's own code) runs it directly.
//
// Internal resistance, sag under load, rest voltage and time left, estimated from the voltage / current / remaining-charge samples the app already shows.
// The time enters as an argument (seconds, strictly increasing): no clock and no randomness here.
//
// Samples come at 4 Hz from the displayed frame, like the charts of the Analysis tab. Everything computed here is an ESTIMATE from those samples: the
// resistance is not measured, the sag and the rest voltage follow from it, and the time left extrapolates the recent slope of `rem`.

using System;
using System.Collections.Generic;

namespace WebGL.Telemetry
{
    public struct BatterySample
    {
        /// <summary>Seconds, strictly increasing within a state.</summary>
        public double t;
        /// <summary>Pack voltage, V.</summary>
        public double v;
        /// <summary>Battery current, A.</summary>
        public double i;
        /// <summary>Remaining charge 0..1.</summary>
        public double rem;

        public BatterySample(double t, double v, double i, double rem) { this.t = t; this.v = v; this.i = i; this.rem = rem; }
    }

    /// <summary>The estimator's memory: the newest samples (oldest first) and the last accepted resistances (oldest first). The web keeps it immutable; here Push mutates.</summary>
    public sealed class BatteryEstimator
    {
        /// <summary>The newest `RingLength` samples, oldest first.</summary>
        public readonly List<BatterySample> samples = new List<BatterySample>(BatteryHealth.RingLength);
        /// <summary>The last `MedianOf` accepted resistances, ohms, oldest first.</summary>
        public readonly List<double> accepted = new List<double>(BatteryHealth.MedianOf);

        public void Clear() { samples.Clear(); accepted.Clear(); }
        public bool HasLast => samples.Count > 0;
        public BatterySample Last => samples[samples.Count - 1];
    }

    public struct BatteryTimeLeft
    {
        /// <summary>Slope of `rem`, 1/s (null when there is not enough history).</summary>
        public double? slope;
        /// <summary>Seconds to the reserve by the slope of `rem`; null = "—" (on the ground, no slope, or the charge is not falling).</summary>
        public double? bySlopeS;
        /// <summary>Seconds to the reserve by the capacity and the mean current (simulator only: `capacityAh` given); null = "—".</summary>
        public double? byCurrentS;
    }

    /// <summary>Everything the section shows, from a state.</summary>
    public struct BatteryReport
    {
        /// <summary>R-hat of the pack, ohms; null while "calculating".</summary>
        public double? rHat;
        /// <summary>R-hat per cell, ohms.</summary>
        public double? rCell;
        /// <summary>Accepted pairs behind R-hat (0..15).</summary>
        public int quality;
        /// <summary>Sag under load dV = R-hat * I, V.</summary>
        public double? dropV;
        /// <summary>Rest voltage V0 = V + dV, V, and per cell.</summary>
        public double? restV, restCell;
        public double? slope, bySlopeS, byCurrentS;
        /// <summary>The newest sample (hasLast false before the first).</summary>
        public bool hasLast;
        public BatterySample last;
    }

    public enum BatterySource { Replay, Sim, Sitl }

    public struct BatteryOrigins
    {
        public ReadingOrigin v, i, rem;
        /// <summary>R-hat, dV, V0 and the time left: always an estimate.</summary>
        public ReadingOrigin derived;
        /// <summary>True in the simulator and in PX4 SITL (and own sessions): the estimate is made on simulated data.</summary>
        public bool onSimData;
    }

    /// <summary>The voltage-against-current chart: the samples as points of a width x height box (x = current, y = voltage, y down) and the fitted line.</summary>
    public sealed class ViCloud
    {
        public double[] x = Array.Empty<double>(), y = Array.Empty<double>();
        public int count;
        /// <summary>The line V = V0 - R-hat * I across the box (x0, y0, x1, y1); hasLine false while calculating.</summary>
        public bool hasLine;
        public double lineX0, lineY0, lineX1, lineY1;
        public double iMin, iMax, vMin, vMax;
    }

    public static class BatteryHealth
    {
        /// <summary>A pair needs a current step of at least this many amps ...</summary>
        public const double MinDeltaA = 3;
        /// <summary>... between the new sample and the most recent one that is at most this many seconds older.</summary>
        public const double MaxDtS = 2;
        /// <summary>The window of samples the estimator looks at, seconds (the pairing only reaches back `MaxDtS` of it).</summary>
        public const double WindowS = 10;
        /// <summary>A pair is accepted when 0 &lt; r &lt; this, ohms (the whole pack).</summary>
        public const double RMaxOhm = 0.2;
        /// <summary>R-hat is the median of the last this many accepted pairs.</summary>
        public const int MedianOf = 15;
        /// <summary>Fewer accepted pairs than this: "calculating".</summary>
        public const int MinAccepted = 5;
        /// <summary>Window of the slope of `rem` and of the mean current, seconds.</summary>
        public const double SlopeWindowS = 30;
        /// <summary>Fewest samples and shortest span (s) for a slope.</summary>
        public const int SlopeMinSamples = 20;
        public const double SlopeMinSpanS = 5;
        /// <summary>The time left needs the charge to fall faster than this, 1/s.</summary>
        public const double SlopeMaxPerS = -1e-5;
        /// <summary>Remaining charge at which the time left ends (PX4 BAT_LOW_THR, AlertThresholds.batteryLowRem).</summary>
        public const double ReserveRem = 0.15;
        /// <summary>Capacity of the simulator's battery, Ah (SimLimits.CapacityAh): the one source where it is known.</summary>
        public const double SimCapacityAh = 5;
        /// <summary>Samples kept (60 s at 4 Hz): also the cloud of the voltage-against-current chart.</summary>
        public const int RingLength = HistoryConstants.Length;
        public const int SampleHz = HistoryConstants.SampleHz;

        static bool Finite(double x) => !double.IsNaN(x) && !double.IsInfinity(x);

        /// <summary>
        /// Appends the sample. For the new sample it looks back (at most `MaxDtS`) for the most recent one whose current differs by `MinDeltaA` or more and
        /// takes r = -dV/dI; the pair counts when 0 &lt; r &lt; `RMaxOhm`. A sample that does not go forward in time is ignored (returns false).
        /// </summary>
        public static bool Push(BatteryEstimator state, BatterySample s)
        {
            if (!Finite(s.t) || !Finite(s.v) || !Finite(s.i) || !Finite(s.rem)) return false;
            List<BatterySample> prev = state.samples;
            if (prev.Count > 0 && s.t <= prev[prev.Count - 1].t) return false;
            for (int j = prev.Count - 1; j >= 0; j--)
            {
                double dt = s.t - prev[j].t;
                if (dt > MaxDtS || dt > WindowS) break;
                double di = s.i - prev[j].i;
                if (Math.Abs(di) < MinDeltaA) continue;
                double r = -(s.v - prev[j].v) / di;
                if (r > 0 && r < RMaxOhm)
                {
                    state.accepted.Add(r);
                    if (state.accepted.Count > MedianOf) state.accepted.RemoveRange(0, state.accepted.Count - MedianOf);
                }
                break; // only the most recent sample with a big enough step is used, accepted or not
            }
            if (prev.Count >= RingLength) prev.RemoveRange(0, prev.Count - RingLength + 1);
            prev.Add(s);
            return true;
        }

        public static double Median(IReadOnlyList<double> xs)
        {
            int n = xs.Count;
            if (n == 0) return double.NaN;
            var a = new double[n];
            for (int i = 0; i < n; i++) a[i] = xs[i];
            Array.Sort(a);
            return n % 2 == 1 ? a[(n - 1) / 2] : (a[n / 2 - 1] + a[n / 2]) / 2;
        }

        /// <summary>Internal resistance of the whole pack, ohms: the median of the accepted pairs, or null while fewer than `MinAccepted` have been accepted.</summary>
        public static double? Resistance(BatteryEstimator state) => state.accepted.Count >= MinAccepted ? Median(state.accepted) : (double?)null;

        /// <summary>Index of the first sample of the last `windowS` seconds (the newest one included); samples.Count when there are none.</summary>
        static int FirstOfLast(IReadOnlyList<BatterySample> samples, double windowS)
        {
            int n = samples.Count;
            if (n == 0) return 0;
            double t0 = samples[n - 1].t - windowS;
            int first = n;
            for (int k = n - 1; k >= 0 && samples[k].t >= t0 - 1e-9; k--) first = k; // t is strictly increasing: the window is a suffix
            return first;
        }

        /// <summary>Least-squares slope of `rem` against time over the last `SlopeWindowS`, 1/s; null with too few samples or too short a span.</summary>
        public static double? RemSlope(IReadOnlyList<BatterySample> samples)
        {
            int first = FirstOfLast(samples, SlopeWindowS);
            int n = samples.Count - first;
            if (n < SlopeMinSamples || samples[samples.Count - 1].t - samples[first].t < SlopeMinSpanS) return null;
            double st = 0, sr = 0;
            for (int k = first; k < samples.Count; k++) { st += samples[k].t; sr += samples[k].rem; }
            double mt = st / n, mr = sr / n;
            double num = 0, den = 0;
            for (int k = first; k < samples.Count; k++)
            {
                num += (samples[k].t - mt) * (samples[k].rem - mr);
                den += (samples[k].t - mt) * (samples[k].t - mt);
            }
            return den > 0 ? num / den : (double?)null;
        }

        /// <summary>Mean current over the last `SlopeWindowS`, A (null without samples).</summary>
        public static double? MeanCurrent(IReadOnlyList<BatterySample> samples)
        {
            int first = FirstOfLast(samples, SlopeWindowS);
            int n = samples.Count - first;
            if (n == 0) return null;
            double a = 0;
            for (int k = first; k < samples.Count; k++) a += samples[k].i;
            return a / n;
        }

        /// <summary>Time left to the 15 % reserve. Only while flying; `capacityAh` only where the capacity is known (the simulator).</summary>
        public static BatteryTimeLeft TimeLeft(IReadOnlyList<BatterySample> samples, bool flying, double? capacityAh = null)
        {
            var r = new BatteryTimeLeft { slope = RemSlope(samples) };
            if (!flying || samples.Count == 0) return r;
            BatterySample last = samples[samples.Count - 1];
            double usable = Math.Max(0, last.rem - ReserveRem);
            if (r.slope.HasValue && r.slope.Value < SlopeMaxPerS) r.bySlopeS = usable / -r.slope.Value;
            double? mean = MeanCurrent(samples);
            if (capacityAh.HasValue && mean.HasValue && mean.Value > 0) r.byCurrentS = (usable * capacityAh.Value * 3600) / mean.Value;
            return r;
        }

        /// <summary>Everything the section shows. `cells` = hello.batteryCells; `flying` = armed and not landed; `capacityAh` known only in the simulator.</summary>
        public static BatteryReport Health(BatteryEstimator state, int cells, bool flying, double? capacityAh = null)
        {
            var h = new BatteryReport { hasLast = state.samples.Count > 0, quality = state.accepted.Count };
            if (h.hasLast) h.last = state.samples[state.samples.Count - 1];
            h.rHat = Resistance(state);
            if (cells <= 0) cells = 4;
            BatteryTimeLeft t = TimeLeft(state.samples, flying, capacityAh);
            if (h.rHat.HasValue && h.hasLast) h.dropV = h.rHat.Value * h.last.i;
            if (h.dropV.HasValue && h.hasLast) h.restV = h.last.v + h.dropV.Value;
            if (h.rHat.HasValue) h.rCell = h.rHat.Value / cells;
            if (h.restV.HasValue) h.restCell = h.restV.Value / cells;
            h.slope = t.slope;
            h.bySlopeS = t.bySlopeS;
            h.byCurrentS = t.byCurrentS;
            return h;
        }

        /// <summary>
        /// Origin of each value. V: measured in the replay, simulated in the simulator and PX4 SITL. I: from `hello.provenance.batteryCurrent` in the replay
        /// (measured) and SITL (the bridge estimates it), simulated in the simulator. `rem`: the PX4 estimate in the replay, simulated elsewhere. An own session
        /// (tool 7) replays simulated readings: all simulated. A missing `batteryCurrent` (older servers; `current` null) is read as measured in the replay and
        /// estimated in SITL.
        /// </summary>
        public static BatteryOrigins Origins(BatterySource source, string current, bool own = false)
        {
            const ReadingOrigin M = ReadingOrigin.Measured, E = ReadingOrigin.Estimated, S = ReadingOrigin.Simulated;
            if (own || source == BatterySource.Sim) return new BatteryOrigins { v = S, i = S, rem = S, derived = E, onSimData = true };
            ReadingOrigin? cur = current == "measured" ? M : current == "estimated" ? E : (ReadingOrigin?)null;
            if (source == BatterySource.Replay) return new BatteryOrigins { v = M, i = cur ?? M, rem = E, derived = E, onSimData = false };
            return new BatteryOrigins { v = S, i = cur ?? E, rem = S, derived = E, onSimData = true };
        }

        /// <summary>
        /// The voltage-against-current chart: the cloud of the samples (the ring: the last 60 s) and the line V = V0 - R-hat * I through the newest one. The
        /// ranges are those of the data (and of the line's ends), widened to at least `minI` A and `minV` V and centred. `into` is reused (no allocation once
        /// its arrays have grown).
        /// </summary>
        public static ViCloud Cloud(IReadOnlyList<BatterySample> samples, double? rHat, double width, double height, ViCloud into = null, double minI = 6, double minV = 0.5)
        {
            ViCloud c = into ?? new ViCloud();
            int n = samples.Count;
            c.count = n;
            c.hasLine = false;
            if (n == 0) { c.iMin = c.iMax = c.vMin = c.vMax = 0; return c; }
            double iLo = double.PositiveInfinity, iHi = double.NegativeInfinity, vLo = double.PositiveInfinity, vHi = double.NegativeInfinity;
            for (int k = 0; k < n; k++)
            {
                BatterySample s = samples[k];
                if (s.i < iLo) iLo = s.i;
                if (s.i > iHi) iHi = s.i;
                if (s.v < vLo) vLo = s.v;
                if (s.v > vHi) vHi = s.v;
            }
            BatterySample last = samples[n - 1];
            double spanI = Math.Max(iHi - iLo, minI);
            double iMin = (iHi + iLo) / 2 - spanI / 2;
            double iMax = iMin + spanI;
            double v0 = rHat.HasValue ? last.v + rHat.Value * last.i : 0;
            double r = rHat ?? 0;
            if (rHat.HasValue)
            {
                vLo = Math.Min(vLo, Math.Min(v0 - r * iMin, v0 - r * iMax));
                vHi = Math.Max(vHi, Math.Max(v0 - r * iMin, v0 - r * iMax));
            }
            double spanV = Math.Max(vHi - vLo, minV);
            double vMin = (vHi + vLo) / 2 - spanV / 2;
            double vMax = vMin + spanV;
            if (c.x.Length < n) { c.x = new double[Math.Max(n, RingLength)]; c.y = new double[Math.Max(n, RingLength)]; }
            for (int k = 0; k < n; k++)
            {
                c.x[k] = (samples[k].i - iMin) / spanI * width;
                c.y[k] = height - (samples[k].v - vMin) / spanV * height;
            }
            if (rHat.HasValue)
            {
                c.hasLine = true;
                c.lineX0 = 0;
                c.lineY0 = height - (v0 - r * iMin - vMin) / spanV * height;
                c.lineX1 = width;
                c.lineY1 = height - (v0 - r * iMax - vMin) / spanV * height;
            }
            c.iMin = iMin; c.iMax = iMax; c.vMin = vMin; c.vMax = vMax;
            return c;
        }
    }
}
